"""Generated MIM mappings follow MIM's explicit CC BY 4.0 data policy (#788)."""

import csv
import hashlib
import io
import json
from pathlib import Path

import pytest
import yaml
from test_mim_owned_name_export import builder
from test_mim_owned_name_export import cli as cli
from test_mim_stable_identity import stable_cli as stable_cli


def metadata_and_rows(path):
    """Keep quoted multiline cells intact while reading actual generated bytes."""
    lines = path.read_text().splitlines(keepends=True)
    end = 0
    while end < len(lines) and lines[end].startswith("#"):
        end += 1
    metadata = yaml.safe_load("".join(line[1:] for line in lines[:end]))
    rows = list(csv.DictReader(io.StringIO("".join(lines[end:])), delimiter="\t", strict=True))
    return metadata, rows


@pytest.mark.parametrize("fixture_name", ["cli", "stable_cli"])
def test_native_generated_mapping_metadata_uses_mim_data_license(request, fixture_name):
    fixture = request.getfixturevalue(fixture_name)
    original_source = fixture["canonical"].read_bytes()
    output, sidecar, manifest = fixture["run"]()
    metadata, rows = metadata_and_rows(output)

    assert metadata["license"] == "https://creativecommons.org/licenses/by/4.0/"
    assert len(rows) == 1
    assert rows[0]["subject_id"] == (
        "MIM:0000002" if fixture_name == "stable_cli" else "MIM:Subject"
    )
    assert rows[0]["predicate_id"] == "skos:exactMatch"
    assert rows[0]["object_id"] == "CHEBI:1"
    assert rows[0]["other"] == "safe"
    assert rows[0]["validation_method"] == (
        "" if fixture_name == "stable_cli" else "prior-reviewed-stamp"
    )
    assert fixture["canonical"].read_bytes() == original_source
    assert sidecar.is_file()
    publication = json.loads(manifest.read_bytes())
    assert publication["identity_mode"] == (
        "stable" if fixture_name == "stable_cli" else "legacy"
    )
    for artifact in publication["artifacts"]:
        assert hashlib.sha256(Path(artifact["path"]).read_bytes()).hexdigest() == artifact["sha256"]


def test_generated_empty_stable_table_uses_mim_data_license(tmp_path):
    output = tmp_path / "empty.sssom.tsv"
    prefix = "https://culturebotai.github.io/MediaIngredientMech/ingredient/MIM_"
    builder._write_sssom([], output, mim_prefix=prefix, empty_version="2026-01-01")
    builder._STABLE_PRODUCER.validate_empty_candidate(output, builder.COLUMNS, prefix)

    metadata, rows = metadata_and_rows(output)
    assert metadata["license"] == "https://creativecommons.org/licenses/by/4.0/"
    assert metadata["curie_map"]["MIM"] == prefix
    assert rows == []
